<template>
  <div class="webCfgContianer">
    <div class="nav"><div style="color: #fff;font-weight: bold;">UTIS配置文件修改服务</div><el-button type="primary" plain size="mini" @click="logoutFun">退出登录</el-button></div>
    <div style="display: flex;justify-content: space-between;">
      <el-menu :default-active="componentIs" class="menuClass" background-color="#4ca1af" text-color="#fff" active-text-color="#ffd04b" @select="menuSelect">
        <el-menu-item v-for="(v, i) in devices" :key="i" :index="v.device_type">
          <span slot="title">{{ v.device_name }}</span>
        </el-menu-item>
      </el-menu>
      <div class="componentClass">
        <component :is="componentIs" :filepath="filepath"></component>
      </div>
    </div>
  </div>
</template>
<script>
import { logout } from '@/api/login'
export default {
  name: 'webCfg',
  data() {
    return{
      componentIs: 'jingShiDeng',
      devices: JSON.parse(sessionStorage.getItem('devices')),
      filepath: ''
    }
  },
  methods: {
    menuSelect(index) {
      // this.$confirm('请确定当前页面是否有未保存数据', '提示', {
      //   confirmButtonText: '确定',
      //   cancelButtonText: '取消',
      //   type: 'warning'
      // }).then(() => {
        if (this.$route.query.redirect !== index) {
          this.$router.replace({
            path: this.$route.path,  // 保持当前路径
            query: {
              redirect: index  // 添加/修改的参数
            }
          })
          this.componentIs = index
          this.filepath = this.devices.filter((filt) => { return filt.device_type == index })[0].filepath
        }
      // }).catch(() => {
      // });
    },
    logoutFun() {
      logout().then(() => {
        this.$router.push('/login')
      })
    }
  },
  created(){
    this.componentIs = this.$route.query.redirect
    this.filepath = this.devices.filter((filt) => { return filt.device_type == this.componentIs })[0].filepath
  }
}
</script>
